const ROBO_ROOT = __DIR__;
const ROBO_BASE = '/robo';

function redirect_to(string $route): never { header('Location: ' . ROBO_BASE . $route, true, 303); exit; }
function render_view(string $view, array $data = []): never { extract($data, EXTR_SKIP); require ROBO_ROOT . '/views/' . $view . '.php'; exit; }
function client_ip(): string { return substr((string) ($_SERVER['REMOTE_ADDR'] ?? '0.0.0.0'), 0, 45); }
function json_response(array $payload, int $status = 200): never { http_response_code($status); header('Content-Type: application/json; charset=utf-8'); header('Cache-Control: no-store'); echo json_encode($payload, JSON_UNESCAPED_UNICODE | JSON_THROW_ON_ERROR); exit; }
function flash_set(string $kind, string $message): void { $_SESSION['_robo_flash'] = ['kind' => $kind, 'message' => $message]; }
function flash_take(): array { $flash = $_SESSION['_robo_flash'] ?? []; unset($_SESSION['_robo_flash']); return is_array($flash) ? $flash : []; }
function request_path(): string { $path = (string) (parse_url((string) ($_SERVER['REQUEST_URI'] ?? '/'), PHP_URL_PATH) ?? '/'); return trim((string) preg_replace('#^/robo/?#', '', $path), '/'); }
function input_json(): array { $body = file_get_contents('php://input'); $data = json_decode($body === false ? '' : $body, true); return is_array($data) ? $data : []; }
function csrf_request(): void { Csrf::verify($_SERVER['HTTP_X_CSRF_TOKEN'] ?? $_POST['_csrf'] ?? null); }

function current_user(PDO $pdo): ?array {
    $id = Session::userId();
    if ($id === null) return null;
    $query = $pdo->prepare('SELECT u.id, u.username, u.role_code, r.label_cs AS role_label_cs, r.label_en AS role_label_en, r.permissions_json FROM users u JOIN roles r ON r.code = u.role_code WHERE u.id = :id AND u.is_active = 1');
    $query->execute(['id' => $id]);
    $user = $query->fetch();
    if ($user === false) { Session::logout(); return null; }
    $user['permissions'] = json_decode((string) $user['permissions_json'], true, 512, JSON_THROW_ON_ERROR);
    return $user;
}
function require_user(PDO $pdo): array { $user = current_user($pdo); if ($user === null) redirect_to('/login'); return $user; }
function permission(array $user, string $name): bool { return $user['role_code'] === 'administrator' || in_array('*', $user['permissions'], true) || in_array($name, $user['permissions'], true); }
function request_expects_json(): bool { return str_starts_with(request_path(), 'api/') || str_contains(strtolower((string) ($_SERVER['HTTP_ACCEPT'] ?? '')), 'application/json'); }
function require_permission(array $user, string $name): void { if (permission($user, $name)) return; if (request_expects_json()) json_response(['error' => 'Pro tuto akci nemáte oprávnění.'], 403); http_response_code(403); header('Content-Type: text/html; charset=utf-8'); echo '<!doctype html><html lang="cs"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>ROBO — Přístup odepřen</title><link rel="stylesheet" href="'.ROBO_BASE.'/assets/app.css"></head><body class="login-page"><main class="login-card"><h1>ROBO</h1><h2>Přístup odepřen</h2><p class="status status-error">Pro tuto stránku nemáte oprávnění.</p><p><a class="button button-primary" href="'.ROBO_BASE.landing_route($user).'">Přejít na dostupnou stránku</a></p></main></body></html>'; exit; }
function landing_route(array $user): string { return match ((string) ($user['role_code'] ?? '')) { 'track_1' => '/track-1', 'track_2' => '/track-2', 'viewer', 'guest' => '/standings', default => '/technical' }; }
function active_competition(PDO $pdo): array { $competition=(new CompetitionRepository($pdo))->active(); $count=$pdo->prepare('SELECT COUNT(*) FROM teams WHERE competition_id=:competition_id');$count->execute(['competition_id'=>$competition['id']]);$actual=(int)$count->fetchColumn();if($actual!==(int)$competition['team_count']){$update=$pdo->prepare('UPDATE competitions SET team_count=:team_count WHERE id=:id');$update->execute(['team_count'=>$actual,'id'=>$competition['id']]);$competition['team_count']=$actual;}return $competition; }
function team_count(PDO $pdo, int $competitionId): int { $statement=$pdo->prepare('SELECT COUNT(*) FROM teams WHERE competition_id=:competition_id'); $statement->execute(['competition_id'=>$competitionId]); return (int)$statement->fetchColumn(); }
function incomplete_technical_count(array $teams): int { return count(array_filter($teams, static fn(array $team): bool => ($team['complete'] ?? false) !== true)); }
function incomplete_ride_count(array $teams): int { return count(array_filter($teams, static fn(array $team): bool => (int)($team['confirmed'] ?? 0) !== 1)); }
function state(PDO $pdo, int $competitionId): array {
    $sql = 'SELECT t.id, t.team_number AS number, t.school_name AS school, t.contestant_names AS members, i.criterion_1, i.criterion_2, i.criterion_3, i.note, COALESCE(i.penalty_seconds, 0) AS technical_penalty, COALESCE(i.is_passed, 0) AS passed, COALESCE(r.checkpoint_1,0) checkpoint_1, COALESCE(r.checkpoint_2,0) checkpoint_2, COALESCE(r.checkpoint_3,0) checkpoint_3, COALESCE(r.checkpoint_4,0) checkpoint_4, COALESCE(r.checkpoint_5,0) checkpoint_5, COALESCE(r.checkpoint_6,0) checkpoint_6, COALESCE(r.finish_count,0) finish, r.lap_1_ms time_1, r.lap_2_ms time_2, r.lap_3_ms time_3, r.lap_4_ms time_4, r.lap_5_ms time_5, r.best_time_ms best_time, COALESCE(r.did_not_stop,0) did_not_stop, COALESCE(r.is_confirmed,0) confirmed FROM teams t LEFT JOIN technical_inspections i ON i.team_id=t.id AND i.competition_id=t.competition_id LEFT JOIN rides r ON r.team_id=t.id AND r.competition_id=t.competition_id WHERE t.competition_id=:competition_id ORDER BY t.team_number';
    $query = $pdo->prepare($sql); $query->execute(['competition_id' => $competitionId]); $teams = $query->fetchAll();
    foreach ($teams as &$team) { for ($i=1;$i<=3;$i++) { $team['condition_'.$i] = match ($team['criterion_'.$i] ?? 'unknown') { 'passed' => 'pass', 'failed' => 'fail', default => 'pending' }; } $team['complete'] = !in_array('unknown', [$team['criterion_1'] ?? 'unknown', $team['criterion_2'] ?? 'unknown', $team['criterion_3'] ?? 'unknown'], true); }
    unset($team); return $teams;
}
function catalog_texts(string $page, string $locale): array { $language=$locale==='en'?'en':'cs'; $values=[]; foreach(PageTextCatalog::entries() as $entry) if($entry['page_key']===$page) $values[$entry['text_key']]=(string)$entry['text_'.$language]; return $values; }
function localized_texts(PDO $pdo, int $competitionId, string $page, string $locale): array { $query=$pdo->prepare('SELECT text_key,text_value FROM page_texts WHERE competition_id=:competition_id AND page_key=:page_key AND locale=:locale');$query->execute(['competition_id'=>$competitionId,'page_key'=>$page,'locale'=>$locale]);return array_replace(catalog_texts($page,$locale),$query->fetchAll(PDO::FETCH_KEY_PAIR)); }
function all_localized_texts(PDO $pdo, int $competitionId, string $locale): array { $query=$pdo->prepare('SELECT page_key,text_key,text_value FROM page_texts WHERE competition_id=:competition_id AND locale=:locale');$query->execute(['competition_id'=>$competitionId,'locale'=>$locale]);$values=[];foreach(PageTextCatalog::pages() as $page)$values[$page['key']]=catalog_texts($page['key'],$locale);foreach($query->fetchAll() as $row)$values[(string)$row['page_key']][(string)$row['text_key']]=(string)$row['text_value'];return $values; }
function ui_text(string $page, string $key, string $fallback): string { $value=$GLOBALS['_robo_ui_texts'][$page][$key]??null;return is_string($value)&&$value!==''?$value:$fallback; }
function ranking(PDO $pdo, int $competitionId): array {
    $items = (new RankingService($pdo))->qualification($competitionId); $rows=[];
    foreach ($items as $row) { $rows[]=['team_id'=>(int)$row['team_id'],'number'=>(int)$row['team_number'],'school'=>(string)$row['school_name'],'members'=>(string)$row['contestant_names'],'checkpoint_1'=>(int)($row['checkpoint_1']??0),'checkpoint_2'=>(int)($row['checkpoint_2']??0),'checkpoint_3'=>(int)($row['checkpoint_3']??0),'checkpoint_4'=>(int)($row['checkpoint_4']??0),'checkpoint_5'=>(int)($row['checkpoint_5']??0),'checkpoint_6'=>(int)($row['checkpoint_6']??0),'finish'=>(int)($row['finish_count']??0),'best_time'=>$row['best_time_ms']===null?null:(int)$row['best_time_ms'],'did_not_stop'=>(int)($row['did_not_stop']??0),'stop_penalty'=>(int)($row['stop_penalty_seconds']??0),'technical_penalty'=>(int)($row['technical_penalty_seconds']??0),'total_time'=>$row['final_time_ms']===null?null:(int)$row['final_time_ms'],'rank'=>$row['rank']===null?null:(int)$row['rank'],'furthest_checkpoint'=>'checkpoint_'.(int)$row['furthest_checkpoint']]; }
    return $rows;
}
function page_state(array $competition, array $user, string $page, int $pending): array { $locale=(string)$competition['locale'];return ['year'=>(string)$competition['competition_year'],'locale'=>$locale,'user'=>(string)$user['username'],'role_label'=>(string)($user[$locale==='cs'?'role_label_cs':'role_label_en']??$user['role_code']),'teams'=>(int)$competition['team_count'],'pending'=>$pending,'saved_at'=>date('H:i:s'),'page'=>$page,'role_code'=>(string)$user['role_code'],'permissions'=>is_array($user['permissions'] ?? null)?$user['permissions']:[]]; }
function xlsx_column(int $number): string { $label=''; while($number>0){$number--; $label=chr(65+$number%26).$label; $number=intdiv($number,26);} return $label; }
function xlsx_download(string $filename, array $sheets): never {
    if (!class_exists('ZipArchive')) { http_response_code(501); exit('Server nemá dostupné rozšíření ZIP potřebné pro export XLSX.'); }
    $temp=tempnam(sys_get_temp_dir(),'robo-xlsx-'); $zip=new ZipArchive(); $zip->open($temp,ZipArchive::OVERWRITE);
    $zip->addFromString('[Content_Types].xml','<?xml version="1.0" encoding="UTF-8"?><Types xmlns="http://schemas.openxmlformats.org/package/2006/content-types"><Default Extension="rels" ContentType="application/vnd.openxmlformats-package.relationships+xml"/><Default Extension="xml" ContentType="application/xml"/><Override PartName="/xl/workbook.xml" ContentType="application/vnd.openxmlformats-officedocument.spreadsheetml.sheet.main+xml"/>'.implode('',array_map(static fn($i)=>'<Override PartName="/xl/worksheets/sheet'.($i+1).'.xml" ContentType="application/vnd.openxmlformats-officedocument.spreadsheetml.worksheet+xml"/>',array_keys($sheets))).'</Types>');
    $zip->addFromString('_rels/.rels','<?xml version="1.0" encoding="UTF-8"?><Relationships xmlns="http://schemas.openxmlformats.org/package/2006/relationships"><Relationship Id="rId1" Type="http://schemas.openxmlformats.org/officeDocument/2006/relationships/officeDocument" Target="xl/workbook.xml"/></Relationships>');
    $book=[];$rels=[];foreach(array_values($sheets) as $offset=>$sheet){$index=$offset+1;$book[]='<sheet name="'.htmlspecialchars($sheet['name'],ENT_XML1|ENT_QUOTES,'UTF-8').'" sheetId="'.$index.'" r:id="rId'.$index.'"/>';$rels[]='<Relationship Id="rId'.$index.'" Type="http://schemas.openxmlformats.org/officeDocument/2006/relationships/worksheet" Target="worksheets/sheet'.$index.'.xml"/>'; $xml='<?xml version="1.0" encoding="UTF-8"?><worksheet xmlns="http://schemas.openxmlformats.org/spreadsheetml/2006/main"><sheetData>';foreach($sheet['rows'] as $rowIndex=>$row){$xml.='<row r="'.($rowIndex+1).'">';foreach(array_values($row) as $column=>$value){$cell=xlsx_column($column+1).($rowIndex+1);$xml.='<c r="'.$cell.'" t="inlineStr"><is><t>'.htmlspecialchars((string)$value,ENT_XML1|ENT_QUOTES,'UTF-8').'</t></is></c>';} $xml.='</row>';} $xml.='</sheetData></worksheet>';$zip->addFromString('xl/worksheets/sheet'.$index.'.xml',$xml);}
    $zip->addFromString('xl/workbook.xml','<?xml version="1.0" encoding="UTF-8"?><workbook xmlns="http://schemas.openxmlformats.org/spreadsheetml/2006/main" xmlns:r="http://schemas.openxmlformats.org/officeDocument/2006/relationships"><sheets>'.implode('',$book).'</sheets></workbook>');$zip->addFromString('xl/_rels/workbook.xml.rels','<?xml version="1.0" encoding="UTF-8"?><Relationships xmlns="http://schemas.openxmlformats.org/package/2006/relationships">'.implode('',$rels).'</Relationships>');$zip->close();header('Content-Type: application/vnd.openxmlformats-officedocument.spreadsheetml.sheet');header('Content-Disposition: attachment; filename="'.$filename.'"');header('Content-Length: '.filesize($temp));readfile($temp);@unlink($temp);exit;
}
function display_time(?int $milliseconds): string { if($milliseconds===null||$milliseconds<=0)return '';return sprintf('%02d:%02d:%03d',intdiv($milliseconds,60000),intdiv($milliseconds%60000,1000),$milliseconds%1000); }
function write_php_config(string $dsn, string $dbUser, string $dbPassword, bool $secure): void { $target=ROBO_ROOT.'/config/local.php'; $temp=$target.'.tmp'; $data=['db_dsn'=>$dsn,'db_user'=>$dbUser,'db_password'=>$dbPassword,'app_secret'=>bin2hex(random_bytes(32)),'secure_cookie'=>$secure,'base_path'=>ROBO_BASE]; if (file_put_contents($temp,"<?php\ndeclare(strict_types=1);\n\nreturn ".var_export($data,true).";\n",LOCK_EX)===false || !rename($temp,$target)) { @unlink($temp); throw new RuntimeException('Konfiguraci nelze uložit.'); } @chmod($target,0640); }
function seed_database(PDO $pdo, string $admin, string $password): void { $pdo->beginTransaction(); try { $pdo->prepare('INSERT INTO competitions (competition_year, competition_date, locale, team_count, is_active) VALUES (:year,:date,\'cs\',16,1)')->execute(['year'=>(int)date('Y'),'date'=>date('Y-m-d')]); $cid=(int)$pdo->lastInsertId(); $pdo->prepare('INSERT INTO users (username,password_hash,role_code) VALUES (:username,:password_hash,\'administrator\')')->execute(['username'=>$admin,'password_hash'=>password_hash($password,PASSWORD_DEFAULT)]); $team=$pdo->prepare('INSERT INTO teams (competition_id,team_number) VALUES (:competition_id,:team_number)'); for($i=1;$i<=16;$i++) $team->execute(['competition_id'=>$cid,'team_number'=>$i]); $penalty=$pdo->prepare('INSERT INTO penalties (competition_id,code,label_cs,label_en,seconds_value) VALUES (:competition_id,:code,:cs,:en,:value)'); $penalty->execute(['competition_id'=>$cid,'code'=>'technical','cs'=>'Technická přejímka','en'=>'Technical inspection','value'=>90]); $penalty->execute(['competition_id'=>$cid,'code'=>'not_stopped','cs'=>'Nezastavení','en'=>'Did not stop','value'=>5]); $pdo->commit(); } catch(Throwable $e) { $pdo->rollBack(); throw $e; } }

if (!is_file(ROBO_ROOT.'/config/local.php')) { header('Location: '.ROBO_BASE.'/install.php',true,302); exit; }
$config=robo_config(ROBO_ROOT); Session::start($config->bool('secure_cookie', true)); $pdo=robo_database($config)->pdo(); $route=request_path(); $method=strtoupper((string)($_SERVER['REQUEST_METHOD']??'GET'));
if ($route==='login') { $competition=active_competition($pdo); $locale=(string)$competition['locale']==='en'?'en':'cs'; $labels=localized_texts($pdo,(int)$competition['id'],'login',$locale); if($method==='POST'){ csrf_request(); $auth=new AuthService($pdo,new RateLimiter($pdo),new AuditLogger($pdo)); $result=$auth->attempt(trim((string)($_POST['username']??'')),(string)($_POST['password']??''),client_ip(),new DateTimeImmutable()); if($result['ok']) redirect_to(landing_route((array)$result['user'])); render_view('login-v045',['csrf'=>Csrf::token(),'year'=>$competition['competition_year'],'locale'=>$locale,'labels'=>$labels,'error'=>$labels['error']??'Přihlášení se nezdařilo. Zkontrolujte zadané údaje nebo kontaktujte správce.']); } render_view('login-v045',['csrf'=>Csrf::token(),'year'=>$competition['competition_year'],'locale'=>$locale,'labels'=>$labels,'error'=>null]); }
if ($route==='logout') { csrf_request(); $logoutUser=current_user($pdo); if($logoutUser!==null)(new AuditLogger($pdo))->log((int)$logoutUser['id'],null,'security.logout','Uživatel se odhlásil.',[],client_ip()); Session::logout(); redirect_to('/login'); }
if ($route==='public' || $route==='api/standings') { $competition=active_competition($pdo); $publicRows=ranking($pdo,(int)$competition['id']); if($route==='api/standings') json_response(['rows'=>$publicRows,'updated_at'=>gmdate(DATE_ATOM)]); render_view('public-display',['locale'=>(string)$competition['locale'],'year'=>(string)$competition['competition_year'],'rows'=>$publicRows,'labels'=>localized_texts($pdo,(int)$competition['id'],'public',(string)$competition['locale'])]); }
$user=require_user($pdo); $competition=active_competition($pdo); $cid=(int)$competition['id'];
$competition['team_count']=team_count($pdo,$cid);
$GLOBALS['_robo_ui_texts']=all_localized_texts($pdo,$cid,(string)$competition['locale']);
$admin = new AdminService($pdo, new AuditLogger($pdo));
$backup = new BackupService($pdo);
$teamsService = new TeamService($pdo, new AuditLogger($pdo));
$updater = new UpdateService();
if (str_starts_with($route, 'system/')) require_permission($user, 'system.view');
try {
    if ($route==='system/competition/save' && $method==='POST') { csrf_request(); $admin->saveCompetition((int)$_POST['id'], (int)$_POST['year'], (string)$_POST['date'], (string)$_POST['locale'], (int)$_POST['team_count'], (int)$user['id'], client_ip()); flash_set('ok','Nastavení ročníku bylo uloženo.'); redirect_to('/system/competition'); }
    if ($route==='system/competition/create' && $method==='POST') { csrf_request(); $id=$admin->createCompetition((int)$_POST['year'], (string)$_POST['date'], (string)$_POST['locale'], (int)$_POST['team_count'], (int)$user['id'], client_ip()); $admin->activateCompetition($id, (int)$user['id'], client_ip()); flash_set('ok','Nový ročník byl vytvořen a aktivován.'); redirect_to('/system/competition'); }
    if ($route==='system/competition/activate' && $method==='POST') { csrf_request(); $admin->activateCompetition((int)$_POST['id'], (int)$user['id'], client_ip()); flash_set('ok','Historický ročník byl aktivován.'); redirect_to('/system/competition'); }
    if ($route==='system/texts/save' && $method==='POST') { csrf_request(); $page=(string)$_POST['page_key']; $key=(string)$_POST['text_key']; if (PageTextCatalog::find($page,$key) === null) throw new RuntimeException('Vybraný text stránky neexistuje v katalogu.'); $admin->savePageText($cid,$page,$key,'cs',(string)$_POST['text_cs'],(int)$user['id'],client_ip()); $admin->savePageText($cid,$page,$key,'en',(string)$_POST['text_en'],(int)$user['id'],client_ip()); flash_set('ok','Texty stránky byly uloženy.'); redirect_to('/system/texts?page='.rawurlencode($page)); }
    if ($route==='system/penalties/save' && $method==='POST') { csrf_request(); $admin->savePenalty($cid,(string)$_POST['code'],(string)$_POST['label_cs'],(string)$_POST['label_en'],(int)$_POST['seconds'],(int)$user['id'],client_ip()); flash_set('ok','Penalizace byla uložena.'); redirect_to('/system/penalties'); }
    if ($route==='system/users/save' && $method==='POST') { csrf_request(); $id=isset($_POST['id']) && $_POST['id']!==''?(int)$_POST['id']:null; $admin->saveUser($id,(string)$_POST['username'],(string)$_POST['role_code'],(string)($_POST['active']??'0')==='1',(string)($_POST['password']??''),(int)$user['id'],client_ip()); flash_set('ok','Uživatelský účet byl uložen.'); redirect_to('/system/users'); }
    if ($route==='system/users/delete' && $method==='POST') { csrf_request(); $admin->deleteUser((int)($_POST['id']??0),(int)$user['id'],client_ip()); flash_set('ok','Uživatelský účet byl smazán.'); redirect_to('/system/users'); }
    if ($route==='system/users/password' && $method==='POST') { csrf_request(); $admin->changeOwnPassword((int)$user['id'],(string)($_POST['current_password']??''),(string)($_POST['new_password']??''),(string)($_POST['password_confirmation']??''),client_ip()); flash_set('ok','Vaše heslo bylo změněno.'); redirect_to('/system/users'); }
    if ($route==='system/teams' && $method==='POST') { csrf_request(); $id=isset($_POST['team_id'])?(int)$_POST['team_id']:null; if(($_POST['action']??'')==='delete') $teamsService->delete($cid,(int)$id,(int)$user['id'],client_ip()); else $teamsService->save($cid,$id,['team_number'=>(int)$_POST['team_number'],'school_name'=>(string)$_POST['school_name'],'contestant_names'=>(string)$_POST['contestant_names']],(int)$user['id'],client_ip()); flash_set('ok','Údaje týmu byly uloženy.'); redirect_to('/system/teams'); }
    if ($route==='system/teams/import-preview' && $method==='POST') { csrf_request(); if(!isset($_FILES['teams_file']) || (int)$_FILES['teams_file']['error']!==UPLOAD_ERR_OK) throw new RuntimeException('Soubor importu nelze načíst.'); $rows=TeamImport::xlsx((string)$_FILES['teams_file']['tmp_name']); $teamsService->validateRows($rows); $_SESSION['team_import_preview']=$rows; render_view('teams-import-preview',['title'=>'Náhled importu týmů','view'=>page_state($competition,$user,'system',0),'csrf'=>Csrf::token(),'rows'=>$rows,'base'=>ROBO_BASE]); }
    if ($route==='system/teams/import-confirm' && $method==='POST') { csrf_request(); $rows=$_SESSION['team_import_preview']??null; if(!is_array($rows)) throw new RuntimeException('Náhled importu vypršel. Nahrajte soubor znovu.'); $teamsService->replaceFromImport($cid,$rows,(int)$user['id'],client_ip()); unset($_SESSION['team_import_preview']); flash_set('ok','Seznam týmů byl nahrazen importem.'); redirect_to('/system/teams'); }
